import React, { useState, useEffect, useCallback } from 'react';

const API = 'http://localhost:5000/api';

export default function AdminDashboard() {
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalGames: 0,
    activeRentals: 0,
    totalRevenue: 0,
    totalRentals: 0,
    totalPurchases: 0,
    availableDigital: 0,
    availablePhysical: 0,
    overdueRentals: 0,
    recentTransactions: []
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const loadStats = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API}/dashboard/stats`);
      const data = await res.json();
      setStats(data);
      setError('');
    } catch (error) {
      console.error('Error loading dashboard stats:', error);
      setError('Failed to load dashboard stats');
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    loadStats();
  }, [loadStats]);

  const formatCurrency = (amount) => {
    return `$${parseFloat(amount).toLocaleString()}`;
  };

  const formatDate = (dateString) => {
    if (!dateString) return '—';
    return new Date(dateString).toLocaleDateString();
  };

  if (loading) {
    return (
      <div>
        <div className="page-header">
          <div>
            <div className="page-title">ADMIN DASHBOARD</div>
            <div className="page-sub">System management</div>
          </div>
        </div>
        <div className="loading"><div className="spinner" /> Loading dashboard...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div>
        <div className="page-header">
          <div>
            <div className="page-title">ADMIN DASHBOARD</div>
            <div className="page-sub">System management</div>
          </div>
        </div>
        <div className="alert alert-error">{error}</div>
      </div>
    );
  }

  return (
    <div>
      <div className="page-header">
        <div>
          <div className="page-title">ADMIN DASHBOARD</div>
          <div className="page-sub">System overview and metrics</div>
        </div>
        <button className="btn btn-cyan" onClick={loadStats}>
          🔄 Refresh
        </button>
      </div>

      <div className="dashboard-grid">
        <div className="stat-card" style={{ 
          background: 'linear-gradient(135deg, rgba(0,240,255,0.1), rgba(157,78,221,0.1))',
          border: '1px solid var(--cyan)'
        }}>
          <div className="stat-icon" style={{ 
            background: 'linear-gradient(135deg, var(--cyan), var(--purple))',
            boxShadow: 'var(--cyan-glow)'
          }}>👥</div>
          <div className="stat-info">
            <div className="stat-val" style={{ color: 'var(--cyan)' }}>{stats.totalUsers}</div>
            <div className="stat-label">Total Users</div>
          </div>
        </div>

        <div className="stat-card" style={{ 
          background: 'linear-gradient(135deg, rgba(0,255,136,0.1), rgba(0,240,255,0.1))',
          border: '1px solid var(--green)'
        }}>
          <div className="stat-icon" style={{ 
            background: 'linear-gradient(135deg, var(--green), var(--cyan))',
            boxShadow: '0 0 20px rgba(0,255,136,0.4)'
          }}>🎮</div>
          <div className="stat-info">
            <div className="stat-val" style={{ color: 'var(--green)' }}>{stats.totalGames}</div>
            <div className="stat-label">Games</div>
          </div>
        </div>

        <div className="stat-card" style={{ 
          background: 'linear-gradient(135deg, rgba(255,107,0,0.1), rgba(0,255,136,0.1))',
          border: '1px solid var(--orange)'
        }}>
          <div className="stat-icon" style={{ 
            background: 'linear-gradient(135deg, var(--orange), var(--green))',
            boxShadow: 'var(--orange-glow)'
          }}>📋</div>
          <div className="stat-info">
            <div className="stat-val" style={{ color: 'var(--orange)' }}>{stats.activeRentals}</div>
            <div className="stat-label">Active Rentals</div>
          </div>
        </div>

        <div className="stat-card" style={{ 
          background: 'linear-gradient(135deg, rgba(220,53,69,0.1), rgba(255,107,0,0.1))',
          border: '1px solid #DC3545'
        }}>
          <div className="stat-icon" style={{ 
            background: 'linear-gradient(135deg, #DC3545, var(--orange))',
            boxShadow: '0 0 20px rgba(220,53,69,0.4)'
          }}>💰</div>
          <div className="stat-info">
            <div className="stat-val" style={{ color: '#DC3545' }}>{formatCurrency(stats.totalRevenue)}</div>
            <div className="stat-label">Total Revenue</div>
          </div>
        </div>

        <div className="stat-card" style={{ 
          background: 'linear-gradient(135deg, rgba(157,78,221,0.1), rgba(0,240,255,0.1))',
          border: '1px solid var(--purple)'
        }}>
          <div className="stat-icon" style={{ 
            background: 'linear-gradient(135deg, var(--purple), var(--cyan))',
            boxShadow: '0 0 20px rgba(157,78,221,0.4)'
          }}>📦</div>
          <div className="stat-info">
            <div className="stat-val" style={{ color: 'var(--purple)' }}>{stats.totalRentals}</div>
            <div className="stat-label">Total Rentals</div>
          </div>
        </div>

        <div className="stat-card" style={{ 
          background: 'linear-gradient(135deg, rgba(0,240,255,0.1), rgba(255,107,0,0.1))',
          border: '1px solid var(--cyan)'
        }}>
          <div className="stat-icon" style={{ 
            background: 'linear-gradient(135deg, var(--cyan), var(--orange))',
            boxShadow: 'var(--cyan-glow)'
          }}>🛒</div>
          <div className="stat-info">
            <div className="stat-val" style={{ color: 'var(--cyan)' }}>{stats.totalPurchases}</div>
            <div className="stat-label">Total Purchases</div>
          </div>
        </div>

        <div className="stat-card" style={{ 
          background: 'linear-gradient(135deg, rgba(0,255,136,0.1), rgba(157,78,221,0.1))',
          border: '1px solid var(--green)'
        }}>
          <div className="stat-icon" style={{ 
            background: 'linear-gradient(135deg, var(--green), var(--purple))',
            boxShadow: '0 0 20px rgba(0,255,136,0.4)'
          }}>💿</div>
          <div className="stat-info">
            <div className="stat-val" style={{ color: 'var(--green)' }}>{stats.availableDigital}</div>
            <div className="stat-label">Digital Copies</div>
          </div>
        </div>

        <div className="stat-card" style={{ 
          background: 'linear-gradient(135deg, rgba(255,107,0,0.1), rgba(220,53,69,0.1))',
          border: '1px solid var(--orange)'
        }}>
          <div className="stat-icon" style={{ 
            background: 'linear-gradient(135deg, var(--orange), #DC3545)',
            boxShadow: 'var(--orange-glow)'
          }}>📀</div>
          <div className="stat-info">
            <div className="stat-val" style={{ color: 'var(--orange)' }}>{stats.availablePhysical}</div>
            <div className="stat-label">Physical Copies</div>
          </div>
        </div>
      </div>

      <div className="dashboard-sections">
        <div className="dashboard-section">
          <div className="section-header">
            <div className="section-title">⚠️ Overdue Rentals</div>
            <div className="section-count" style={{ color: '#DC3545' }}>{stats.overdueRentals}</div>
          </div>
          <div className="section-content" style={{ 
            background: 'rgba(220,53,69,0.1)',
            border: '1px solid rgba(220,53,69,0.3)',
            borderRadius: 'var(--radius)',
            padding: '20px',
            textAlign: 'center'
          }}>
            <div style={{ fontSize: '48px', fontWeight: 'bold', color: '#DC3545', marginBottom: '10px' }}>
              {stats.overdueRentals}
            </div>
            <div style={{ color: 'var(--text2)' }}>Rentals past due date</div>
          </div>
        </div>

        <div className="dashboard-section">
          <div className="section-header">
            <div className="section-title">💰 Recent Transactions</div>
            <div className="section-count">{stats.recentTransactions.length}</div>
          </div>
          <div className="section-content" style={{ 
            background: 'var(--card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            overflow: 'hidden'
          }}>
            {stats.recentTransactions.length === 0 ? (
              <div style={{ padding: '40px', textAlign: 'center', color: 'var(--text2)' }}>
                No recent transactions
              </div>
            ) : (
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ 
                    background: 'linear-gradient(135deg, var(--cyan), var(--purple))',
                    color: 'var(--text)',
                    fontFamily: 'Orbitron, monospace'
                  }}>
                    <th style={{ padding: '12px', textAlign: 'left', fontSize: '12px', letterSpacing: '1px' }}>ID</th>
                    <th style={{ padding: '12px', textAlign: 'left', fontSize: '12px', letterSpacing: '1px' }}>USER</th>
                    <th style={{ padding: '12px', textAlign: 'left', fontSize: '12px', letterSpacing: '1px' }}>TYPE</th>
                    <th style={{ padding: '12px', textAlign: 'left', fontSize: '12px', letterSpacing: '1px' }}>AMOUNT</th>
                  </tr>
                </thead>
                <tbody>
                  {stats.recentTransactions.map((transaction, index) => (
                    <tr key={transaction.TransactionID} style={{ 
                      borderBottom: '1px solid var(--border2)',
                      background: index % 2 === 0 ? 'var(--card2)' : 'var(--card)',
                      fontFamily: 'Rajdhani, sans-serif'
                    }}>
                      <td style={{ padding: '12px', fontSize: '13px', color: 'var(--cyan)', fontWeight: '600' }}>
                        #{transaction.TransactionID}
                      </td>
                      <td style={{ padding: '12px', fontSize: '13px', color: 'var(--text)' }}>
                        {transaction.UserName}
                      </td>
                      <td style={{ padding: '12px', fontSize: '13px' }}>
                        <span style={{ 
                          padding: '4px 10px',
                          borderRadius: '12px',
                          fontSize: '11px',
                          fontWeight: 'bold',
                          background: transaction.TransactionType === 'Rental' ? 'rgba(0,240,255,0.12)' : 'rgba(255,107,0,0.12)',
                          color: transaction.TransactionType === 'Rental' ? 'var(--cyan)' : 'var(--orange)',
                          border: transaction.TransactionType === 'Rental' ? '1px solid var(--cyan)' : '1px solid var(--orange)'
                        }}>
                          {transaction.TransactionType}
                        </span>
                      </td>
                      <td style={{ padding: '12px', fontSize: '13px', color: 'var(--green)', fontWeight: '600', fontFamily: 'Orbitron, monospace' }}>
                        ${parseFloat(transaction.Amount).toFixed(2)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
